/* Saldova modular — fondos fotográficos de los módulos (imágenes de
 * Leonardo, 2026-11-23, comprimidas y viajeras en base64 porque la
 * publicación solo admite texto). Se intercalan: un módulo usa el
 * fondo A (escritorio con portátil y papeles) y el siguiente el B
 * (recibos y calculadora), y así sucesivamente. El fondo lleva un
 * velo claro encima para que el texto se siga leyendo como siempre:
 * SOLO cambia el fondo; tarjetas, tablas y botones quedan igual. */
export const FONDOS = [
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
];
export function aplicarFondo(indice) {
    const f = FONDOS[Math.abs(indice || 0) % FONDOS.length];
    document.body.style.background =
        'linear-gradient(rgba(246,250,253,.42), rgba(230,240,249,.52)), url("' + f + '") center center / cover fixed no-repeat #D8E6F3';
}
